// Locally generated visual samples, not manufacturer product photographs.
export const WALL_MATERIALS=[{id:'plain',name:'Матовая краска',finish:'paint',color:'#e4dfd2',rx:1,ry:1},{id:'linen',name:'Льняное полотно',finish:'wallpaper',color:'#e3d6bd',rx:.53,ry:.8},{id:'botanical',name:'Листья и ветви',finish:'wallpaper',color:'#e5e5d5',rx:.53,ry:.8},{id:'geometry',name:'Мягкая геометрия',finish:'wallpaper',color:'#d4c6b0',rx:.53,ry:.53},{id:'plaster',name:'Минеральная штукатурка',finish:'plaster',color:'#c6bbaa',rx:1,ry:1}];
export const FLOOR_MATERIALS=[{id:'oak',name:'Светлый дуб',finish:'laminate',color:'#c5a77d',rx:.8,ry:1.2},{id:'walnut',name:'Тёплый орех',finish:'laminate',color:'#93704c',rx:.8,ry:1.2},{id:'stone',name:'Тёплый камень',finish:'tile',color:'#c1bcb1',rx:.6,ry:.6},{id:'marble',name:'Светлый мрамор',finish:'tile',color:'#e5e4de',rx:.6,ry:.6}];
export function materialFor(surface,floor=false){const list=floor?FLOOR_MATERIALS:WALL_MATERIALS;return list.find(m=>m.id===surface.texture)||list.find(m=>m.finish===surface.finish)||list[0];}
const cache=new Map();
export function textureCanvas(id,color){const key=id+color;if(cache.has(key))return cache.get(key);const tile=document.createElement('canvas');tile.width=384;tile.height=512;const c=tile.getContext('2d'),W=384,H=512;let seed=49217;const random=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296;};c.fillStyle=color;c.fillRect(0,0,W,H);
 for(let i=0;i<18000;i++){c.fillStyle=random()<.5?'#ffffff13':'#30271810';c.fillRect(random()*W,random()*H,1+random()*2,1+random()*2);}
 if(id==='linen'){for(let x=0;x<W;x+=2){c.strokeStyle=x%4?'#78644519':'#ffffff48';c.lineWidth=.6+random();c.beginPath();c.moveTo(x,0);c.lineTo(x+random()*1.5,H);c.stroke();}for(let y=0;y<H;y+=3){c.fillStyle=y%2?'#fff4':'#50452215';c.fillRect(0,y,W,.6);}}
 if(id==='botanical'){for(const [x,y,angle] of [[80,145,-.3],[280,390,.3]]){c.save();c.translate(x,y);c.rotate(angle);c.strokeStyle='#52684c77';c.lineWidth=2;c.beginPath();c.moveTo(0,110);c.bezierCurveTo(-22,55,20,-35,0,-115);c.stroke();for(let n=0;n<7;n++){const yy=80-n*26,side=n%2?-1:1;c.save();c.translate(Math.sin(n)*7,yy);c.rotate(side*.7);c.fillStyle=n%3?'#65795580':'#83916a85';c.beginPath();c.ellipse(side*15,-9,11,29,side*.4,0,2*Math.PI);c.fill();c.strokeStyle='#e2e4cb66';c.lineWidth=.6;c.beginPath();c.moveTo(side*8,5);c.lineTo(side*23,-30);c.stroke();c.restore();}c.restore();}}
 if(id==='geometry'){c.strokeStyle='#6f604b55';c.lineWidth=2;for(let y=-128;y<H+128;y+=128)for(let x=-96;x<W+96;x+=96){const offset=(y/128)%2?48:0;c.beginPath();c.ellipse(x+offset,y,45,90,0,Math.PI,2*Math.PI);c.stroke();c.strokeStyle='#fff7';c.beginPath();c.ellipse(x+offset+3,y+3,38,83,0,Math.PI,2*Math.PI);c.stroke();c.strokeStyle='#6f604b55';}}
 if(id==='plaster'||id==='stone'){for(let i=0;i<1000;i++){c.fillStyle=random()<.5?'#ffffff08':'#41332507';c.beginPath();c.ellipse(random()*W,random()*H,5+random()*55,3+random()*25,random()*3,0,Math.PI*2);c.fill();}for(let i=0;i<1600;i++){c.fillStyle='#51463114';c.fillRect(random()*W,random()*H,random()*3,random()*2);}}
 if(id==='oak'||id==='walnut'){for(let b=0;b<4;b++){const left=b*96;c.save();c.beginPath();c.rect(left,0,96,H);c.clip();c.fillStyle=b%2?'#fff1':'#3425150a';c.fillRect(left,0,96,H);for(let i=0;i<95;i++){const x=left+random()*96;c.beginPath();for(let y=0;y<=H;y+=8){const wave=Math.sin(y/64+i)*2+Math.sin(y/170+i)*3;y?c.lineTo(x+wave,y):c.moveTo(x+wave,y);}c.strokeStyle=i%3?'#49311d20':'#fff3';c.lineWidth=.4+random()*.8;c.stroke();}const ky=100+b*97;for(let n=1;n<=8;n++){c.strokeStyle='#4e321b22';c.lineWidth=.7;c.beginPath();c.ellipse(left+40,ky,n*2,n*8,0,0,2*Math.PI);c.stroke();}c.fillStyle='#38281835';c.fillRect(left,0,1.2,H);c.fillRect(left,b%2?H*.5:0,96,1.5);c.restore();}}
 if(id==='marble'){for(let k=0;k<7;k++){c.beginPath();let x=random()*W,y=0;c.moveTo(x,y);while(y<H){x+=(random()-.48)*35;y+=12;c.lineTo(x,y);}c.strokeStyle=k%2?'#77786c30':'#ffffff88';c.lineWidth=1+random()*2;c.stroke();}}
 if(id==='stone'||id==='marble'){c.strokeStyle='#7b796244';c.lineWidth=3;c.strokeRect(1,1,W-2,H-2);c.strokeStyle='#fff7';c.lineWidth=1;c.strokeRect(3,3,W-6,H-6);}
 cache.set(key,tile);if(cache.size>60)cache.delete(cache.keys().next().value);return tile;}
export function sampleURL(id,color){return textureCanvas(id,color).toDataURL('image/png');}
export function paintMaterial(c,point,polygon,origin,u,v,width,height,surface,floor=false){const m=materialFor(surface,floor),tile=textureCanvas(m.id,surface.color),a=point(...origin),b=point(origin[0]+u[0]*m.rx,origin[1]+u[1]*m.rx,origin[2]+u[2]*m.rx),d=point(origin[0]+v[0]*m.ry,origin[1]+v[1]*m.ry,origin[2]+v[2]*m.ry);const A=(b[0]-a[0])/tile.width,B=(b[1]-a[1])/tile.width,C=(d[0]-a[0])/tile.height,D=(d[1]-a[1])/tile.height;if(Math.abs(A*D-B*C)<1e-9)return;c.save();c.beginPath();polygon.forEach((p,i)=>i?c.lineTo(...point(...p)):c.moveTo(...point(...p)));c.closePath();c.clip();c.transform(A,B,C,D,a[0],a[1]);c.fillStyle=c.createPattern(tile,'repeat');c.fillRect(0,0,width/m.rx*tile.width,height/m.ry*tile.height);c.restore();}
